"use client";
// @zeus-internal
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS, ARTEMIS_SPRING_LAYOUT } from "../../../lib/ease";
import { RangeSlider } from "./08-ledger/range-slider";
import { NumberTicker } from "./08-ledger/number-ticker";
const plans = [
    { name: "Core", base: 24, included: 5, extra: 6, description: "For focused teams shipping their first production workflows.", features: ["Unlimited projects", "50k monthly events", "Community support"] },
    { name: "Scale", base: 64, included: 10, extra: 5, description: "For growing teams that need observability and control.", features: ["500k monthly events", "Audit history", "Priority support"] },
    { name: "Enterprise", base: 180, included: 25, extra: 4, description: "For organizations with security and procurement requirements.", features: ["Unlimited events", "SAML and SCIM", "Dedicated success manager"] },
] as const;
export default function PricingLedger() {
    const [annual, setAnnual] = useState(true);
    const [selected, setSelected] = useState(1);
    const [seats, setSeats] = useState(12);
    const reduced = useReducedMotion();
    const billingId = useId();
    const planId = useId();
    const plan = plans[selected];
    const extraSeats = Math.max(0, seats - plan.included);
    const extraCost = extraSeats * plan.extra;
    const total = Math.round((plan.base + extraCost) * (annual ? 0.8 : 1));
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-4 art:py-20 art:@min-[640px]/artemis:px-8">
          <div className="art:mx-auto art:w-full art:max-w-6xl art:border art:border-border/60 art:bg-background">
            <header className="art:grid art:gap-6 art:border-border/60 art:border-b art:p-6 art:@min-[640px]/artemis:p-8 art:@min-[1024px]/artemis:grid-cols-[1fr_auto] art:@min-[1024px]/artemis:items-end">
              <div>
                <p className="art:font-mono art:text-xs art:text-primary art:uppercase art:tracking-[0.17em]">
                  {"Pricing ledger"}
                </p>
                <h2 className="art:mt-5 art:max-w-2xl art:text-balance art:text-4xl art:font-medium art:text-foreground art:leading-[1.02] art:tracking-[-0.04em]">
                  {"A price you can explain line by line."}
                </h2>
              </div>
              <fieldset className="art:flex art:border art:border-border/70">
                <legend className="art:sr-only">
                  {"Billing period"}
                </legend>
                <motion.button whileHover={reduced ? undefined : { scale: 1.01 }} whileTap={reduced ? undefined : { scale: 0.98 }} transition={ARTEMIS_SPRING_PRESS} onClick={() => setAnnual(false)} type="button" className={`art:items-center art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:focus-visible:outline-none art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:inline-block art:p-0 art:font-normal art:hover:bg-transparent art:relative art:h-10 art:min-w-24 art:px-4 art:font-mono art:text-xs art:uppercase art:tracking-[0.12em] art:outline-none art:focus-visible:ring-2 art:focus-visible:ring-inset art:focus-visible:ring-foreground art:rounded-full ${!annual ? "art:hover:text-inherit art:text-primary-foreground" : "art:text-muted-foreground art:hover:text-foreground"}`} aria-pressed={!annual} tabIndex={0}>
                  {!annual && <motion.span layoutId={billingId} className="art:absolute art:inset-0 art:bg-primary" transition={ARTEMIS_SPRING_LAYOUT}/>}
                  <span className="art:relative">
                    {"monthly"}
                    {" "}
